
-- Real subscription entitlements for worker and large-driver operating radius,
-- tier-ranked dispatch, taxi high-demand alerts/lookup, and priority support.
ALTER TABLE public.worker_profiles ADD COLUMN IF NOT EXISTS service_radius_km integer NOT NULL DEFAULT 25 CHECK(service_radius_km BETWEEN 1 AND 55);
ALTER TABLE public.driver_profiles ADD COLUMN IF NOT EXISTS service_radius_km integer NOT NULL DEFAULT 25 CHECK(service_radius_km BETWEEN 1 AND 55);
ALTER TABLE public.support_conversations ADD COLUMN IF NOT EXISTS priority_tier integer NOT NULL DEFAULT 0 CHECK(priority_tier BETWEEN 0 AND 3);
CREATE INDEX IF NOT EXISTS support_conversations_priority_updated_idx ON public.support_conversations(priority_tier DESC,updated_at ASC) WHERE status='open';

UPDATE public.subscription_plans SET features=COALESCE(features,'{}'::jsonb)||CASE code
 WHEN 'silver' THEN '{"worker_max_radius_km":40,"large_driver_max_radius_km":40,"taxi_high_demand_alerts":true,"taxi_priority_dispatch":true,"taxi_fast_support":true}'::jsonb
 WHEN 'gold' THEN '{"worker_max_radius_km":55,"large_driver_max_radius_km":55,"taxi_high_demand_alerts":true,"taxi_priority_dispatch":true,"taxi_fast_support":true,"taxi_instant_alerts":true,"taxi_top_priority":true,"taxi_high_demand_lookup":true}'::jsonb
 ELSE '{}'::jsonb END WHERE code IN ('silver','gold');

CREATE TABLE IF NOT EXISTS public.provider_demand_alert_log(
 user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
 zone_key text NOT NULL,last_notified_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(user_id,zone_key)
);
ALTER TABLE public.provider_demand_alert_log ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.provider_demand_alert_log FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.provider_demand_alert_log TO service_role;

CREATE OR REPLACE FUNCTION public.find_nearby_drivers(_lat numeric, _lng numeric, _category text, _radius_km numeric DEFAULT 5, _limit integer DEFAULT 10) RETURNS TABLE(user_id uuid, distance_km numeric, rating_avg numeric) LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $function$ SELECT x.user_id, x.distance_km, x.rating_avg FROM ( SELECT DISTINCT ON (dp.user_id) dp.user_id, dp.rating_avg, COALESCE(sp.priority_weight, 0) AS subscription_priority, ( 6371 * acos(LEAST(1.0, GREATEST(-1.0, cos(radians(_lat)) * cos(radians(loc.lat)) * cos(radians(loc.lng) - radians(_lng)) + sin(radians(_lat)) * sin(radians(loc.lat)) ))) )::numeric AS distance_km FROM public.driver_profiles dp JOIN ( SELECT pp.user_id, pp.lat, pp.lng, pp.updated_at FROM public.provider_presence pp UNION ALL SELECT ll.user_id, ll.lat, ll.lng, ll.updated_at FROM public.live_locations ll ) loc ON loc.user_id = dp.user_id LEFT JOIN public.user_subscriptions us ON us.user_id=dp.user_id AND us.status='active' AND (us.current_period_end IS NULL OR us.current_period_end>now()) LEFT JOIN public.subscription_plans sp ON sp.id=us.plan_id WHERE dp.available = true AND public.mamnoon_provider_subscription_active(dp.user_id) AND dp.status = 'approved' AND ( dp.suspended_until IS NULL OR dp.suspended_until <= now() ) AND ( _category IS NULL OR dp.vehicle_category::text = _category ) AND ( ( _category = 'large' AND EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = dp.user_id AND ur.role = 'large_driver'::public.app_role) ) OR ( _category IS DISTINCT FROM 'large' AND _category IN ('economy', 'premium', 'luxury') AND EXISTS (SELECT 1 FROM public.user_roles ur WHERE ur.user_id = dp.user_id AND ur.role = 'driver'::public.app_role) ) ) AND loc.updated_at > now() - interval '5 minutes' AND NOT EXISTS ( SELECT 1 FROM public.service_requests sr WHERE sr.provider_id = dp.user_id AND sr.status IN ('accepted', 'in_progress') ) AND NOT EXISTS ( SELECT 1 FROM public.user_blocks b WHERE b.user_id = dp.user_id AND ( b.expires_at IS NULL OR b.expires_at > now() ) ) ORDER BY dp.user_id, loc.updated_at DESC ) x WHERE x.distance_km <= LEAST(GREATEST(COALESCE(_radius_km, 5), 0.1), 55) AND (_category IS DISTINCT FROM 'large' OR x.distance_km <= COALESCE((SELECT LEAST(COALESCE(dp.service_radius_km,25), CASE COALESCE(sp2.code,'bronze') WHEN 'gold' THEN 55 WHEN 'silver' THEN 40 ELSE 25 END) FROM public.driver_profiles dp LEFT JOIN public.user_subscriptions us2 ON us2.user_id=dp.user_id AND us2.status='active' AND (us2.current_period_end IS NULL OR us2.current_period_end>now()) LEFT JOIN public.subscription_plans sp2 ON sp2.id=us2.plan_id WHERE dp.user_id=x.user_id),25)) ORDER BY x.subscription_priority DESC, x.distance_km ASC, x.rating_avg DESC NULLS LAST LIMIT LEAST(GREATEST(COALESCE(_limit, 10), 1), 250); $function$;

CREATE OR REPLACE FUNCTION public.advance_service_dispatch(_request_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE r public.service_requests%ROWTYPE; q public.service_dispatch_queue%ROWTYPE; v_radius numeric; v_min numeric; v_count integer := 0; BEGIN SELECT * INTO r FROM public.service_requests WHERE id = _request_id FOR UPDATE; SELECT * INTO q FROM public.service_dispatch_queue WHERE request_id = _request_id FOR UPDATE; IF NOT FOUND THEN RETURN 0; END IF; IF r.type <> 'service' OR r.status NOT IN ('pending', 'searching') OR r.provider_id IS NOT NULL OR r.service_id IS NULL THEN DELETE FROM public.service_dispatch_queue WHERE request_id = _request_id; RETURN 0; END IF; IF q.next_at > now() THEN RETURN 0; END IF; IF q.stage >= 8 THEN DELETE FROM public.service_dispatch_queue WHERE request_id = _request_id; INSERT INTO public.notifications(user_id, type, title, body, link, data) VALUES ( r.customer_id, 'service_searching', 'انتهى البحث ضمن 55 كم', 'لم نعثر على فني متاح ضمن مسافة 55 كم. يمكنك إعادة المحاولة لاحقاً.', '/request/' || r.id, jsonb_build_object('request_id', r.id, 'service_id', r.service_id, 'max_radius_km', 55) ); RETURN 0; END IF; UPDATE public.request_offers SET status = 'expired', responded_at = now() WHERE request_id = _request_id AND status = 'pending' AND expires_at <= now(); v_radius := (ARRAY[2, 5, 10, 15, 20, 25, 40, 55]::numeric[])[q.stage + 1]; v_min := (ARRAY[0, 2, 5, 10, 15, 20, 25, 40]::numeric[])[q.stage + 1]; WITH latest_presence AS ( SELECT DISTINCT ON (pp.user_id) pp.user_id, pp.lat, pp.lng, pp.updated_at FROM public.provider_presence pp WHERE pp.updated_at > now() - interval '5 minutes' ORDER BY pp.user_id, pp.updated_at DESC ), candidates AS ( SELECT wp.user_id, (6371 * acos(LEAST(1.0, GREATEST(-1.0, cos(radians(r.pickup_lat::double precision)) * cos(radians(lp.lat)) * cos(radians(lp.lng) - radians(r.pickup_lng::double precision)) + sin(radians(r.pickup_lat::double precision)) * sin(radians(lp.lat)) ))))::numeric AS distance_km, COALESCE(sp.priority_weight, 0) AS subscription_priority, LEAST(COALESCE(wp.service_radius_km,25), CASE COALESCE(sp.code,'bronze') WHEN 'gold' THEN 55 WHEN 'silver' THEN 40 ELSE 25 END) AS effective_radius_km FROM public.worker_profiles wp JOIN public.worker_services ws ON ws.worker_id = wp.user_id AND ws.service_id = r.service_id JOIN latest_presence lp ON lp.user_id = wp.user_id LEFT JOIN public.user_subscriptions us ON us.user_id=wp.user_id AND us.status='active' AND (us.current_period_end IS NULL OR us.current_period_end>now()) LEFT JOIN public.subscription_plans sp ON sp.id=us.plan_id WHERE wp.available = true AND public.mamnoon_provider_subscription_active(wp.user_id) AND wp.status = 'approved' AND (r.level_required IS NULL OR wp.level = r.level_required) AND r.pickup_lat IS NOT NULL AND r.pickup_lng IS NOT NULL AND NOT EXISTS ( SELECT 1 FROM public.service_requests active WHERE active.provider_id = wp.user_id AND active.status IN ('accepted', 'in_progress') ) AND NOT EXISTS ( SELECT 1 FROM public.user_blocks b WHERE b.user_id = wp.user_id AND (b.expires_at IS NULL OR b.expires_at > now()) ) ), inserted AS ( INSERT INTO public.request_offers (request_id, provider_id, distance_km, status, sent_at, expires_at) SELECT r.id, c.user_id, c.distance_km, 'pending', now(), now() + interval '60 seconds' FROM candidates c WHERE c.distance_km > v_min AND c.distance_km <= v_radius AND c.distance_km <= c.effective_radius_km AND c.user_id <> r.customer_id AND NOT EXISTS ( SELECT 1 FROM public.request_offers existing WHERE existing.request_id = r.id AND existing.provider_id = c.user_id AND existing.status IN ('pending', 'accepted', 'rejected') ) ORDER BY c.subscription_priority DESC, c.distance_km ASC LIMIT 10 ON CONFLICT (request_id, provider_id) DO UPDATE SET status = 'pending', distance_km = EXCLUDED.distance_km, sent_at = now(), expires_at = now() + interval '60 seconds', responded_at = NULL WHERE public.request_offers.status IN ('expired', 'cancelled') RETURNING id, provider_id, distance_km ) INSERT INTO public.notifications (user_id, type, title, body, link, data) SELECT i.provider_id, 'service_offer', 'طلب خدمة جديد', 'وصلك طلب ' || s.name_ar || ' بالقرب منك. لديك دقيقة للرد.', '/request/' || r.id, jsonb_build_object( 'request_id', r.id, 'offer_id', i.id, 'service_id', r.service_id, 'service_slug', s.slug, 'service_name', s.name_ar, 'distance_km', round(i.distance_km, 2), 'price_iqd', COALESCE(r.customer_price, r.price_estimate), 'pickup_text', r.pickup_text, 'work_description', r.work_description, 'workers_count', r.workers_count, 'dispatch_radius_km', v_radius ) FROM inserted i JOIN public.services s ON s.id = r.service_id; GET DIAGNOSTICS v_count = ROW_COUNT; UPDATE public.service_dispatch_queue SET stage = q.stage + 1, next_at = now() + interval '60 seconds' WHERE request_id = _request_id; RETURN v_count; END; $function$;

CREATE OR REPLACE FUNCTION public.advance_taxi_dispatch(_request_id uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE r public.service_requests%ROWTYPE; q public.taxi_dispatch_queue%ROWTYPE; v_radius numeric; v_min numeric; v_count integer := 0; BEGIN SELECT * INTO r FROM public.service_requests WHERE id = _request_id FOR UPDATE; IF NOT FOUND THEN DELETE FROM public.taxi_dispatch_queue WHERE request_id = _request_id; RETURN 0; END IF; SELECT * INTO q FROM public.taxi_dispatch_queue WHERE request_id = _request_id FOR UPDATE; IF NOT FOUND THEN RETURN 0; END IF; IF r.status NOT IN ('pending', 'searching') OR r.provider_id IS NOT NULL THEN DELETE FROM public.taxi_dispatch_queue WHERE request_id = _request_id; RETURN 0; END IF; IF q.next_at > now() THEN RETURN 0; END IF; UPDATE public.request_offers SET status = 'expired', responded_at = now() WHERE request_id = _request_id AND status = 'pending' AND expires_at <= now(); -- السيارات الكبيرة
IF r.vehicle_category::text = 'large' THEN IF q.stage >= 8 THEN DELETE FROM public.taxi_dispatch_queue WHERE request_id = _request_id; INSERT INTO public.notifications( user_id, type, title, body, link, data ) VALUES ( r.customer_id, 'large_vehicle_searching', 'انتهى البحث ضمن 55 كم', 'لم تصل عروض من أصحاب السيارات الكبيرة ضمن 55 كم. يمكنك إعادة إرسال الطلب.', '/request/' || r.id, jsonb_build_object( 'request_id', r.id, 'max_radius_km', 55 ) ); RETURN 0; END IF; v_radius := (ARRAY[2, 5, 10, 15, 20, 25, 40, 55]::numeric[])[q.stage + 1]; v_min := (ARRAY[0, 2, 5, 10, 15, 20, 25, 40]::numeric[])[q.stage + 1]; WITH inserted AS ( INSERT INTO public.request_offers( request_id, provider_id, distance_km, status, sent_at, expires_at ) SELECT r.id, d.user_id, d.distance_km, 'pending', now(), now() + interval '24 hours' FROM public.find_nearby_drivers( r.pickup_lat, r.pickup_lng, 'large', v_radius, 250 ) d JOIN public.driver_profiles dp ON dp.user_id = d.user_id WHERE d.distance_km > v_min AND d.user_id <> r.customer_id AND ( r.vehicle_type IS NULL OR dp.vehicle_type = r.vehicle_type ) AND NOT EXISTS ( SELECT 1 FROM public.request_offers o WHERE o.request_id = r.id AND o.provider_id = d.user_id AND o.status IN ('pending', 'accepted', 'rejected') ) ORDER BY COALESCE((SELECT sp.priority_weight FROM public.user_subscriptions us JOIN public.subscription_plans sp ON sp.id=us.plan_id WHERE us.user_id=d.user_id AND us.status='active' AND (us.current_period_end IS NULL OR us.current_period_end>now()) LIMIT 1),0) DESC, d.distance_km ASC LIMIT 100 ON CONFLICT (request_id, provider_id) DO UPDATE SET status = 'pending', distance_km = EXCLUDED.distance_km, sent_at = now(), expires_at = now() + interval '24 hours', responded_at = NULL, proposed_price = NULL, offer_message = NULL WHERE public.request_offers.status IN ('expired', 'cancelled') RETURNING provider_id ) INSERT INTO public.notifications( user_id, type, title, body, link, data ) SELECT i.provider_id, 'ride_offer', 'طلب سيارة كبيرة جديد', 'وصل طلب كيا حمل/ركاب ضمن نطاقك. أرسل سعرك للزبون.', '/request/' || r.id, jsonb_build_object( 'request_id', r.id, 'vehicle_type', r.vehicle_type, 'pickup_text', r.pickup_text, 'dest_text', r.dest_text, 'customer_price', r.customer_price, 'dispatch_radius_km', v_radius ) FROM inserted i; GET DIAGNOSTICS v_count = ROW_COUNT; UPDATE public.taxi_dispatch_queue SET stage = q.stage + 1, next_at = now() + interval '60 seconds' WHERE request_id = _request_id; RETURN v_count; END IF; -- انتهاء مراحل البحث للتاكسي الاعتيادي
IF q.stage >= 3 THEN DELETE FROM public.taxi_dispatch_queue WHERE request_id = _request_id; UPDATE public.service_requests SET status = 'cancelled', cancellation_reason = 'لم يقبل أي سائق الطلب ضمن نطاق 5 كم', cancelled_by = NULL WHERE id = _request_id; UPDATE public.request_offers SET status = 'cancelled', responded_at = now() WHERE request_id = _request_id AND status = 'pending'; INSERT INTO public.notifications( user_id, type, title, body, link, data ) VALUES ( r.customer_id, 'request_cancelled', 'انتهى البحث عن سائق', 'لم يقبل أي سائق الطلب ضمن مسافة 5 كم. يمكنك المحاولة مرة أخرى.', '/request/' || _request_id, jsonb_build_object( 'request_id', _request_id, 'max_radius_km', 5 ) ); RETURN 0; END IF; v_radius := (ARRAY[1, 3, 5]::numeric[])[q.stage + 1]; v_min := (ARRAY[0, 1, 3]::numeric[])[q.stage + 1]; -- توزيع التاكسي الاعتيادي مع السماح بإعادة العروض المنتهية والملغاة
WITH inserted AS ( INSERT INTO public.request_offers( request_id, provider_id, distance_km, status, sent_at, expires_at ) SELECT _request_id, d.user_id, d.distance_km, 'pending', now(), now() + interval '60 seconds' FROM public.find_nearby_drivers( r.pickup_lat, r.pickup_lng, r.vehicle_category::text, v_radius, 100 ) d WHERE d.distance_km > v_min AND d.user_id <> r.customer_id AND NOT EXISTS ( SELECT 1 FROM public.request_offers o WHERE o.request_id = _request_id AND o.provider_id = d.user_id AND o.status IN ('pending', 'accepted', 'rejected') ) ORDER BY COALESCE((SELECT sp.priority_weight FROM public.user_subscriptions us JOIN public.subscription_plans sp ON sp.id=us.plan_id WHERE us.user_id=d.user_id AND us.status='active' AND (us.current_period_end IS NULL OR us.current_period_end>now()) LIMIT 1),0) DESC, d.distance_km ASC LIMIT 10 ON CONFLICT (request_id, provider_id) DO UPDATE SET status = 'pending', distance_km = EXCLUDED.distance_km, sent_at = now(), expires_at = now() + interval '60 seconds', responded_at = NULL, proposed_price = NULL, offer_message = NULL WHERE public.request_offers.status IN ('expired', 'cancelled') RETURNING provider_id ) INSERT INTO public.notifications( user_id, type, title, body, link, data ) SELECT provider_id, 'ride_offer', 'طلب رحلة جديد', 'لديك دقيقة لقبول الرحلة من ' || COALESCE(r.pickup_text, 'الموقع المحدد') || ' إلى ' || COALESCE(r.dest_text, 'الوجهة المحددة'), '/request/' || _request_id, jsonb_build_object( 'request_id', _request_id, 'dispatch_radius_km', v_radius ) FROM inserted; GET DIAGNOSTICS v_count = ROW_COUNT; UPDATE public.taxi_dispatch_queue SET stage = q.stage + 1, next_at = now() + interval '60 seconds' WHERE request_id = _request_id; RETURN v_count; END; $function$;

CREATE OR REPLACE FUNCTION public.set_provider_service_radius(p_radius_km integer) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_uid uuid:=auth.uid(); v_code text; v_max integer:=25; v_changed integer:=0; BEGIN IF v_uid IS NULL THEN RAISE EXCEPTION 'unauthorized'; END IF; IF p_radius_km IS NULL OR p_radius_km<1 OR p_radius_km>55 THEN RAISE EXCEPTION 'invalid_radius'; END IF; SELECT sp.code INTO v_code FROM public.user_subscriptions us JOIN public.subscription_plans sp ON sp.id=us.plan_id WHERE us.user_id=v_uid AND us.status='active' AND (us.current_period_end IS NULL OR us.current_period_end>now()) ORDER BY sp.tier DESC LIMIT 1; v_max:=CASE v_code WHEN 'gold' THEN 55 WHEN 'silver' THEN 40 ELSE 25 END; IF p_radius_km>v_max THEN RAISE EXCEPTION 'radius_exceeds_subscription_limit'; END IF; IF public.has_role(v_uid,'worker') THEN UPDATE public.worker_profiles SET service_radius_km=p_radius_km,updated_at=now() WHERE user_id=v_uid; GET DIAGNOSTICS v_changed=ROW_COUNT; END IF; IF public.has_role(v_uid,'large_driver') THEN UPDATE public.driver_profiles SET service_radius_km=p_radius_km,updated_at=now() WHERE user_id=v_uid; GET DIAGNOSTICS v_changed=ROW_COUNT; END IF; IF v_changed=0 THEN RAISE EXCEPTION 'provider_profile_not_found'; END IF; RETURN p_radius_km; END; $function$;

CREATE OR REPLACE FUNCTION public.get_taxi_high_demand_areas(p_category text DEFAULT NULL::text) RETURNS TABLE(zone_lat numeric, zone_lng numeric, waiting_requests integer, online_drivers integer, demand_ratio numeric, demand_level text) LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_uid uuid:=auth.uid(); BEGIN IF v_uid IS NULL OR NOT public.has_role(v_uid,'driver') THEN RAISE EXCEPTION 'taxi_driver_only'; END IF; IF NOT EXISTS(SELECT 1 FROM public.user_subscriptions us JOIN public.subscription_plans sp ON sp.id=us.plan_id WHERE us.user_id=v_uid AND us.status='active' AND (us.current_period_end IS NULL OR us.current_period_end>now()) AND sp.code = 'gold') THEN RAISE EXCEPTION 'gold_required'; END IF; RETURN QUERY WITH demand AS ( SELECT floor(sr.pickup_lat::numeric*100)::integer gy,floor(sr.pickup_lng::numeric*100)::integer gx,count(*)::integer waiting FROM public.service_requests sr WHERE sr.type='taxi' AND sr.status IN ('pending','searching') AND sr.created_at>now()-interval '30 minutes' AND sr.pickup_lat IS NOT NULL AND sr.pickup_lng IS NOT NULL AND (p_category IS NULL OR sr.vehicle_category::text=p_category) GROUP BY 1,2 HAVING count(*)>=2 ), drivers AS ( SELECT floor(pp.lat*100)::integer gy,floor(pp.lng*100)::integer gx,count(DISTINCT pp.user_id)::integer online FROM public.provider_presence pp JOIN public.driver_profiles dp ON dp.user_id=pp.user_id AND dp.available AND dp.status='approved' JOIN public.user_roles ur ON ur.user_id=pp.user_id AND ur.role='driver' WHERE pp.updated_at>now()-interval '5 minutes' GROUP BY 1,2 ) SELECT round(((d.gy+0.5)/100.0)::numeric,3),round(((d.gx+0.5)/100.0)::numeric,3),d.waiting,COALESCE(v.online,0), round(d.waiting::numeric/GREATEST(COALESCE(v.online,0),1),2), CASE WHEN d.waiting::numeric/GREATEST(COALESCE(v.online,0),1)>=2 THEN 'high' ELSE 'medium' END FROM demand d LEFT JOIN drivers v USING(gy,gx) ORDER BY d.waiting::numeric/GREATEST(COALESCE(v.online,0),1) DESC,d.waiting DESC LIMIT 30; END; $function$;

CREATE OR REPLACE FUNCTION public.notify_taxi_driver_high_demand() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_plan text;v_zone text;v_waiting integer;v_log timestamptz; BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles ur WHERE ur.user_id=NEW.user_id AND ur.role='driver') THEN RETURN NEW; END IF; SELECT sp.code INTO v_plan FROM public.user_subscriptions us JOIN public.subscription_plans sp ON sp.id=us.plan_id WHERE us.user_id=NEW.user_id AND us.status='active' AND (us.current_period_end IS NULL OR us.current_period_end>now()) ORDER BY sp.tier DESC LIMIT 1; IF COALESCE(v_plan,'') NOT IN ('silver','gold') THEN RETURN NEW; END IF; SELECT count(*)::integer INTO v_waiting FROM public.service_requests sr WHERE sr.type='taxi' AND sr.status IN ('pending','searching') AND sr.created_at>now()-interval '30 minutes' AND sr.pickup_lat IS NOT NULL AND sr.pickup_lng IS NOT NULL AND 6371*acos(LEAST(1.0,GREATEST(-1.0,cos(radians(NEW.lat))*cos(radians(sr.pickup_lat::double precision))*cos(radians(sr.pickup_lng::double precision)-radians(NEW.lng))+sin(radians(NEW.lat))*sin(radians(sr.pickup_lat::double precision)))))<=2; IF v_waiting<2 THEN RETURN NEW; END IF; v_zone:=floor(NEW.lat*100)::text||':'||floor(NEW.lng*100)::text; INSERT INTO public.provider_demand_alert_log(user_id,zone_key,last_notified_at) VALUES(NEW.user_id,v_zone,now()) ON CONFLICT(user_id,zone_key) DO UPDATE SET last_notified_at=now() WHERE public.provider_demand_alert_log.last_notified_at<now()-interval '15 minutes' RETURNING last_notified_at INTO v_log; IF v_log IS NOT NULL THEN INSERT INTO public.notifications(user_id,type,title,body,link,data) VALUES(NEW.user_id,'taxi_high_demand',CASE WHEN v_plan='gold' THEN 'تنبيه فوري: طلب مرتفع' ELSE 'منطقة طلب مرتفع' END, 'توجد '||v_waiting||' طلبات تكسي قريبة منك ضمن 2 كم. انتقل للمنطقة لزيادة فرص استلام الرحلات.','/profile', jsonb_build_object('waiting_requests',v_waiting,'radius_km',2,'zone_key',v_zone,'plan',v_plan)); END IF; RETURN NEW; END; $function$;

CREATE OR REPLACE FUNCTION public.refresh_support_conversation_priority(p_user_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_tier integer:=0; BEGIN SELECT CASE sp.code WHEN 'gold' THEN 3 WHEN 'silver' THEN 2 WHEN 'bronze' THEN 1 WHEN 'trial' THEN 1 ELSE 0 END INTO v_tier FROM public.user_subscriptions us JOIN public.subscription_plans sp ON sp.id=us.plan_id WHERE us.user_id=p_user_id AND us.status='active' AND (us.current_period_end IS NULL OR us.current_period_end>now()) ORDER BY sp.tier DESC LIMIT 1; UPDATE public.support_conversations SET priority_tier=COALESCE(v_tier,0) WHERE user_id=p_user_id AND status='open'; END; $function$;

CREATE OR REPLACE FUNCTION public.set_new_support_conversation_priority() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ DECLARE v_tier integer:=0; BEGIN SELECT CASE sp.code WHEN 'gold' THEN 3 WHEN 'silver' THEN 2 WHEN 'bronze' THEN 1 WHEN 'trial' THEN 1 ELSE 0 END INTO v_tier FROM public.user_subscriptions us JOIN public.subscription_plans sp ON sp.id=us.plan_id WHERE us.user_id=NEW.user_id AND us.status='active' AND (us.current_period_end IS NULL OR us.current_period_end>now()) ORDER BY sp.tier DESC LIMIT 1; NEW.priority_tier:=COALESCE(v_tier,0); RETURN NEW; END; $function$;

CREATE OR REPLACE FUNCTION public.sync_support_priority_after_subscription_change() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN PERFORM public.refresh_support_conversation_priority(NEW.user_id); RETURN NEW; END; $function$;

REVOKE ALL ON FUNCTION public.set_provider_service_radius(integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.set_provider_service_radius(integer) TO authenticated;
REVOKE ALL ON FUNCTION public.get_taxi_high_demand_areas(text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_taxi_high_demand_areas(text) TO authenticated;
REVOKE ALL ON FUNCTION public.notify_taxi_driver_high_demand() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.refresh_support_conversation_priority(uuid) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.set_new_support_conversation_priority() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.sync_support_priority_after_subscription_change() FROM PUBLIC,anon,authenticated;

DROP TRIGGER IF EXISTS trg_notify_taxi_driver_high_demand ON public.provider_presence;
CREATE TRIGGER trg_notify_taxi_driver_high_demand AFTER INSERT OR UPDATE OF lat,lng,updated_at ON public.provider_presence FOR EACH ROW EXECUTE FUNCTION public.notify_taxi_driver_high_demand();
DROP TRIGGER IF EXISTS trg_support_conversation_priority ON public.support_conversations;
CREATE TRIGGER trg_support_conversation_priority BEFORE INSERT OR UPDATE OF priority_tier,user_id ON public.support_conversations FOR EACH ROW EXECUTE FUNCTION public.set_new_support_conversation_priority();
DROP TRIGGER IF EXISTS trg_sync_support_priority_after_subscription_change ON public.user_subscriptions;
CREATE TRIGGER trg_sync_support_priority_after_subscription_change AFTER INSERT OR UPDATE OF plan_id,status,current_period_end ON public.user_subscriptions FOR EACH ROW EXECUTE FUNCTION public.sync_support_priority_after_subscription_change();


CREATE POLICY provider_demand_alert_log_service_role_only ON public.provider_demand_alert_log FOR ALL TO service_role USING(true) WITH CHECK(true);
CREATE OR REPLACE FUNCTION public.notify_taxi_drivers_on_new_demand()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_zone text;v_waiting integer;
BEGIN
 IF NEW.type<>'taxi' OR NEW.status NOT IN ('pending','searching') OR NEW.pickup_lat IS NULL OR NEW.pickup_lng IS NULL THEN RETURN NEW; END IF;
 SELECT count(*)::integer INTO v_waiting FROM public.service_requests sr
 WHERE sr.type='taxi' AND sr.status IN ('pending','searching') AND sr.created_at>now()-interval '30 minutes'
 AND sr.pickup_lat IS NOT NULL AND sr.pickup_lng IS NOT NULL
 AND 6371*acos(LEAST(1.0,GREATEST(-1.0,cos(radians(NEW.pickup_lat::double precision))*cos(radians(sr.pickup_lat::double precision))*cos(radians(sr.pickup_lng::double precision)-radians(NEW.pickup_lng::double precision))+sin(radians(NEW.pickup_lat::double precision))*sin(radians(sr.pickup_lat::double precision)))))<=2;
 IF v_waiting<2 THEN RETURN NEW; END IF;
 v_zone:=floor(NEW.pickup_lat::numeric*100)::text||':'||floor(NEW.pickup_lng::numeric*100)::text;
 WITH eligible AS (
  SELECT dp.user_id,sp.code plan_code FROM public.driver_profiles dp
  JOIN public.user_roles ur ON ur.user_id=dp.user_id AND ur.role='driver'
  JOIN public.provider_presence pp ON pp.user_id=dp.user_id AND pp.updated_at>now()-interval '5 minutes'
  JOIN public.user_subscriptions us ON us.user_id=dp.user_id AND us.status='active' AND (us.current_period_end IS NULL OR us.current_period_end>now())
  JOIN public.subscription_plans sp ON sp.id=us.plan_id AND sp.code IN ('silver','gold')
  WHERE dp.available=true AND dp.status='approved'
   AND 6371*acos(LEAST(1.0,GREATEST(-1.0,cos(radians(NEW.pickup_lat::double precision))*cos(radians(pp.lat))*cos(radians(pp.lng)-radians(NEW.pickup_lng::double precision))+sin(radians(NEW.pickup_lat::double precision))*sin(radians(pp.lat)))))<=2
 ), logged AS (
  INSERT INTO public.provider_demand_alert_log(user_id,zone_key,last_notified_at)
  SELECT e.user_id,v_zone,now() FROM eligible e
  ON CONFLICT(user_id,zone_key) DO UPDATE SET last_notified_at=now()
   WHERE public.provider_demand_alert_log.last_notified_at<now()-interval '15 minutes'
  RETURNING user_id
 )
 INSERT INTO public.notifications(user_id,type,title,body,link,data)
 SELECT e.user_id,'taxi_high_demand',CASE WHEN e.plan_code='gold' THEN 'تنبيه فوري: طلبات تكسي مرتفعة' ELSE 'تنبيه: منطقة طلب مرتفع' END,
 'ازدادت طلبات التكسي ضمن 2 كم من موقعك. افتح ممنون لاستلام الرحلات المتاحة.','/profile',
 jsonb_build_object('zone_key',v_zone,'waiting_requests',v_waiting,'radius_km',2,'plan',e.plan_code)
 FROM eligible e JOIN logged l ON l.user_id=e.user_id;
 RETURN NEW;
END; $$;
REVOKE ALL ON FUNCTION public.notify_taxi_drivers_on_new_demand() FROM PUBLIC,anon,authenticated;
DROP TRIGGER IF EXISTS trg_notify_taxi_drivers_on_new_demand ON public.service_requests;
CREATE TRIGGER trg_notify_taxi_drivers_on_new_demand AFTER INSERT OR UPDATE OF status,pickup_lat,pickup_lng ON public.service_requests FOR EACH ROW EXECUTE FUNCTION public.notify_taxi_drivers_on_new_demand();


UPDATE public.support_conversations c
SET priority_tier=COALESCE((
 SELECT CASE sp.code WHEN 'gold' THEN 3 WHEN 'silver' THEN 2 WHEN 'bronze' THEN 1 WHEN 'trial' THEN 1 ELSE 0 END
 FROM public.user_subscriptions us JOIN public.subscription_plans sp ON sp.id=us.plan_id
 WHERE us.user_id=c.user_id AND us.status='active' AND (us.current_period_end IS NULL OR us.current_period_end>now())
 ORDER BY sp.tier DESC LIMIT 1
),0)
WHERE c.status='open';
